import{_ as t,o as a,c as o,X as r}from"./chunks/framework.pSp8ynCZ.js";const p=JSON.parse('{"title":"Troubleshooting","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/docs/troubleshooting.md","filePath":"troubleshooting.md"}'),n={name:"rust/docs/troubleshooting.md"};function i(d,e,s,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="a-run-stops-making-progress" tabindex="-1">A run stops making progress <a class="header-anchor" href="#a-run-stops-making-progress" aria-label="Permalink to &quot;A run stops making progress&quot;">​</a></h2><p>Check whether the consumer still holds a batch lease or has stopped consuming an assigned rank. A full output ring blocks the producer. Finish readers and drop leases, or copy outputs into independent storage.</p><p>Do not call the producer synchronously and wait for it to finish before starting consumption when the sequence can fill the ring. Use <code>for_each_batch</code>, or run producer and consumers concurrently. Inspect <code>wait.ring</code>, <code>wait.plan</code>, <code>wait.window</code>, and <code>wait.gen</code> when profiling is enabled.</p><h2 id="io-uring-initialization-fails" tabindex="-1">io_uring initialization fails <a class="header-anchor" href="#io-uring-initialization-fails" aria-label="Permalink to &quot;io_uring initialization fails&quot;">​</a></h2><p>Some kernels or container policies disable io_uring. Select <code>LoaderConfig { backend: IoBackend::Pread, .. }</code> explicitly. Backend creation errors are not an automatic request to change the backend. Check <a href="/cellpack-docs/rust/docs/performance.html">performance</a> when comparing asynchronous and blocking reads.</p><h2 id="direct-i-o-returns-an-error" tabindex="-1">Direct I/O returns an error <a class="header-anchor" href="#direct-i-o-returns-an-error" aria-label="Permalink to &quot;Direct I/O returns an error&quot;">​</a></h2><p>Check filesystem support, stream offset alignment, and page size. Use <code>DataSourceBuilder::direct_io(false)</code> to establish buffered correctness. An embedded stream&#39;s logical page alignment alone does not establish the outer file&#39;s physical offset alignment.</p><h2 id="configuration-or-plan-is-rejected" tabindex="-1">Configuration or plan is rejected <a class="header-anchor" href="#configuration-or-plan-is-rejected" aria-label="Permalink to &quot;Configuration or plan is rejected&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Source page-size mismatch</td><td>All streams use the builder&#39;s declared page size</td></tr><tr><td>Invalid column map</td><td>One entry per source column; distinct in-range targets or <code>UNMAPPED</code></td></tr><tr><td>Invalid schema</td><td>Distinct schema ids and standard ids; compatible conversion and nonzero sizes</td></tr><tr><td>Access count mismatch</td><td>Length is divisible by the number of schemas</td></tr><tr><td>Cell outside the source</td><td>Global registration ranges and paired offsets</td></tr><tr><td>Ring mismatch</td><td>Derive layout with this loader&#39;s <code>ring_layout</code></td></tr><tr><td>Plan mismatch</td><td>Inputs, exact access sequence, schema/process identities, and slot size</td></tr><tr><td>Window too large</td><td>Execution window does not exceed plan reuse gap</td></tr><tr><td>Invalid online options</td><td>Horizon is at least the gap; row and block policies have their required costs</td></tr></tbody></table><h2 id="busy-or-an-unusable-ring" tabindex="-1"><code>Busy</code> or an unusable ring <a class="header-anchor" href="#busy-or-an-unusable-ring" aria-label="Permalink to &quot;`Busy` or an unusable ring&quot;">​</a></h2><p>Only one run may hold a loader and one producer may hold a ring. Drop the previous <code>Run</code>, consume ready output, and release every lease before reuse. An aborted ring remains aborted and must be replaced.</p><p>After a run fails, report the first non-<code>Aborted</code> error when available: cancellation can cause other participants to report <code>Aborted</code> as a consequence. Treat that run as finished with failure and discard incomplete output.</p><h2 id="unexpected-zeros-or-defaults" tabindex="-1">Unexpected zeros or defaults <a class="header-anchor" href="#unexpected-zeros-or-defaults" aria-label="Permalink to &quot;Unexpected zeros or defaults&quot;">​</a></h2><p>A present matrix column with an omitted sparse value is zero. A column absent from that matrix receives the schema default. Verify source-to-standard and output-to-standard maps. A default does not replace present zeros. See <a href="/cellpack-docs/rust/docs/data-sources.html">data sources</a>.</p><h2 id="csr-output-has-unused-capacity" tabindex="-1">CSR output has unused capacity <a class="header-anchor" href="#csr-output-has-unused-capacity" aria-label="Permalink to &quot;CSR output has unused capacity&quot;">​</a></h2><p><code>ReadSpec::nnz</code> is source-based capacity, which can exceed actual output nnz after dropping columns. Use the count returned by <code>read_csr_into</code> and the final row offsets. Bytes beyond actual nnz are not output data.</p><h2 id="memory-exceeds-the-cache-budget" tabindex="-1">Memory exceeds the cache budget <a class="header-anchor" href="#memory-exceeds-the-cache-budget" aria-label="Permalink to &quot;Memory exceeds the cache budget&quot;">​</a></h2><p><code>cache_bytes</code> limits cache frames, not process RSS. Private read buffers, metadata, scratch, output rings, compiler state, allocator overhead, and OS page cache are additional. Use the matching planning mode with <code>memory_estimate_for</code> and measure resident memory separately.</p><h2 id="malformed-data-or-a-failed-decode" tabindex="-1">Malformed data or a failed decode <a class="header-anchor" href="#malformed-data-or-a-failed-decode" aria-label="Permalink to &quot;Malformed data or a failed decode&quot;">​</a></h2><p>Keep chunks, records, decode tables, and value widths matched. The codec trusts inner records; release decoding is not a sanitizer for arbitrary untrusted bytes. After any failing read or decode, discard potentially partial output.</p><h2 id="documentation-build-fails" tabindex="-1">Documentation build fails <a class="header-anchor" href="#documentation-build-fails" aria-label="Permalink to &quot;Documentation build fails&quot;">​</a></h2><ul><li>Use the pinned documentation toolchain from <a href="/cellpack-docs/rust/docs/contributing.html">documentation development</a>.</li><li>Run <code>uv sync --locked --project docs/cellpack</code> for the isolated documentation environment.</li><li>A rustdoc warning is an error; check the reported Rust source link.</li><li>Install the frontend with <code>npm ci --prefix docs/cellpack</code>.</li><li>Missing Markdown links fail the VitePress build; fix the reported target.</li><li>Prepare the API with the build script before starting the frontend directly.</li><li>On Read the Docs, select <code>docs/cellpack/.readthedocs.yaml</code> as the build configuration.</li><li>Follow your compute environment&#39;s policy for compilation and example execution.</li></ul>',23)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
